"""Пути: что считается своей папкой, временным каталогом и можно ли писать в цель."""
import posixpath
import re
from dguard import config
from dguard.config import norm, SCRATCH


def under_cwd(cwd, p):
    """Относительный путь `p` от рабочего каталога `cwd`, нормализованный."""
    return posixpath.normpath(cwd + "/" + p)


def placeholder(p):
    """Нормализованный путь — не путь: пусто, заготовка `<…>` или `{}` (подстановка `find -exec`)."""
    return not p or p.startswith("<") or "{}" in p


def literal_part(p):
    """Буквальная часть нормализованного пути: до первой неизвестной переменной (`$home` — известна)."""
    return re.split(r"\$(?!home\b|\{home\})", p, maxsplit=1)[0] if "$" in p else p


def closed_host(text):
    """В тексте (путь, имя хоста, аргументы ssh) назван закрытый хост из `guard_forbidden_hosts`."""
    return bool(config.CLOSED_RE and config.CLOSED_RE.search(text or ""))


TEMP_VARS = ("$tmp", "$temp", "$tmpdir", "${tmp}", "${temp}", "${tmpdir}", "${tmpdir:-/tmp}", "${tmp:-/tmp}",
             "${temp:-/tmp}", "$env:tmp", "$env:temp", "%tmp%", "%temp%")
TEMP_DIR_MARK = "/appdata/local/temp/"             # %TEMP% Windows (`C:/Users/<имя>/AppData/Local/Temp/…`, в т.ч. короткое имя 8.3)
        if a.startswith("-") and len(a) > 1:
            j += 2 if a in valset else 1
        else:
            break
    if name == "timeout":
        j += 1                                   # длительность
    elif name == "flock" and "-c" not in words[i + 1:j]:
        j += 1                                   # файл блокировки
    return j


def join_cwd(cwd, target, vars_):
    """Новый рабочий каталог после `cd target` или None (не определить)."""
    if not target or target == "-":
        return None
    t = norm(expand_vars(target, vars_))
    if temp_rest(t) is not None:                          # `cd $TMP/x`, `cd "$(mktemp -d)"` — каталог известен как временный
        return posixpath.normpath(t)
    if "$" in t.replace("$home", "").replace("${home}", "") or "%" in t:
        return None
    absolute = t.startswith(("/", "~", "$home", "${home}")) or re.match(r"[a-z]:", t)
    if absolute:
        return posixpath.normpath(t)
    if not cwd:
        return None
    return under_cwd(cwd, t)


def shell_code(args):
    """(строка-код | None, найден ли скрипт-файл) для `bash …`: `-c STRING` либо скрипт/stdin."""
    j = 0
    while j < len(args):
        a = args[j]
        if a in ("-o", "+o", "-O", "+O"):
            j += 2
        elif re.fullmatch(r"-[A-Za-z]*c[A-Za-z]*", a) and j + 1 < len(args):
            return args[j + 1], False
        elif a.startswith(("-", "+")) and a != "-":
            j += 1
        else:
            return None, a != "-"
    elif name in PS_NAMES:
        text = ps_code(args)
        sctx = ctx.copy()
        sctx.via = "ps"
        if text is not None:
            yield from scan_text(text, sctx, (), depth + 1)
    elif name == "cmd":
        for k, a in enumerate(args):
            if a.lower() in ("/c", "/k", "/r"):
                yield from scan_text(" ".join(args[k + 1:]), ctx, (), depth + 1)
                break
    elif name in ("cd", "pushd", "chdir", "set-location", "sl"):
        pos = [a for a in args if not a.startswith("-") or a == "-"]
        ctx.cwd = join_cwd(ctx.cwd, pos[0] if pos else None, vars_)
    elif name == "popd":
        ctx.cwd = None
    else:
        yield from generic_scan(w, name, args, ctx, vars_, sin, depth)


def runner_scan(args, ctx, vars_, sin, depth):
    for k, a in enumerate(args):
        nm = cmd_name(a)
        if (nm in DEL_VERBS or nm in SHELLS or nm in ("find", "git", "rsync", "ssh") or nm in PUBLISH_SUBS
                or nm in HTTP_NAMES or PY_NAMES.match(nm)):
            yield from scan_one(Cmd(args[k:]), ctx, vars_, sin, depth + 1)
def _copy_targets(name, words):
    """→ ([назначения], источники, рекурсивно): `-t КАТАЛОГ` / `--target-directory=` / `of=` / последний путь без флагов."""
    flags = [w for w in words if w.startswith("-") and len(w) > 1]
    pos, to, skip = [], None, False
    for k, w in enumerate(words):
        if skip:
            skip = False
        elif w.lower() in ("-t", "--target-directory", "-destination") and k + 1 < len(words):
            to, skip = words[k + 1], True
        elif w.startswith("--target-directory="):
            to = w.split("=", 1)[1]
        elif w.startswith("of="):
            to = w[3:]
        elif not w.startswith("-") and not w.startswith("if="):
            pos.append(w)
    recursive = name in ("mv", "rsync") or any(re.fullmatch(r"-[a-zA-Z]*[rRa][a-zA-Z]*|--recursive|-recurse", f, re.I) for f in flags)
    if to is not None:
        return [to], pos, recursive
    return pos[-1:], pos[:-1], recursive


def _sub_hit(sub, here, ctx):
    """Путь, в который пишет простая команда (без `|`), если он устав."""
    words = _words(sub)
    while words and re.fullmatch(r"\w+=\S*|sudo|command|env|time|nohup", words[0]):
        words = words[1:]
    name = re.sub(r"\.exe$", "", posixpath.basename(words[0]).lower()) if words else ""
    args = words[1:]
    targets, structured = [], False
    if name in COPY_TO or name == "dd":
        dest, sources, recursive = _copy_targets(name, args)
        for d in dest:
            p = _abs(d, here)
            if _charter_path(p, ctx) or _tree_over_claude(p, sources, recursive, name == "rsync"):
                return d
        for src in sources if name in ("mv", "move", "move-item") else ():      # перенос уносит устав из каталога

